// AI: below section was generated by an AI
// Host-side check of the HUB75 color order pin permutation in wled00/bus_manager.cpp (hub75RemapColorPins).
// Runs with `npm test` (node --test). It reads the lineSrc table, the normalisation range and the M-1 (MOONHUB_S3)
// pinout from the C++ source, simulates the remap, and asserts:
//  - every order permutes the same six GPIOs (pin allocation is unaffected),
//  - stored 0 (factory/default), 1, 7..15 and white-swap values leave the M-1 pins exactly as before (no swap),
//  - order 4 (BGR) gives the same pins as the old r1<->b1 / r2<->b2 swap,
//  - orders 1..5 put the same data on the panel's R/G/B lines as WLED's PolyBus wire order and WLED-MM PR #349,
//  - HUB75-only order 6 is a real red/green swap.
'use strict';
const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const path = require('path');

const src = fs.readFileSync(path.join(__dirname, '..', 'wled00', 'bus_manager.cpp'), 'utf8');

// lineSrc rows: logical channel (0=R 1=G 2=B) sent on the panel's R, G, B input lines, per stored order
const tableText = src.match(/lineSrc\[[^\]]+\]\[3\]\s*=\s*\{([\s\S]*?)\};/);
assert.ok(tableText, 'lineSrc table not found in bus_manager.cpp');
const lineSrc = [...tableText[1].matchAll(/\{\s*(\d)\s*,\s*(\d)\s*,\s*(\d)\s*\}/g)].map(m => [+m[1], +m[2], +m[3]]);
const maxOrder = +src.match(/COL_ORDER_HUB75_GRB\s*=\s*(\d+)/)[1];

// M-1 board wiring (MOONHUB_S3_PINOUT): r1,g1,b1,r2,g2,b2 are the first six entries
const pinText = src.match(/defined\(MOONHUB_S3_PINOUT\)[\s\S]*?mxconfig\.gpio\s*=\s*\{([^}]*)\}/);
assert.ok(pinText, 'MOONHUB_S3_PINOUT pin list not found');
const p = pinText[1].split(',').map(s => +s.trim());
const M1 = { r1: p[0], g1: p[1], b1: p[2], r2: p[3], g2: p[4], b2: p[5] };
const lineOfPin = { [M1.r1]: 'R', [M1.g1]: 'G', [M1.b1]: 'B', [M1.r2]: 'R', [M1.g2]: 'G', [M1.b2]: 'B' };

// hub75ColorOrder(): read its accepted range and fallback from the C++ so a change there is tested too
const normText = src.match(/static uint8_t hub75ColorOrder\(uint8_t co\)\s*\{\s*co &= 0x0F;\s*return \(co >= (\w+) && co <= (\w+)\) \? co : (\w+);/);
assert.ok(normText, 'hub75ColorOrder() body not in the expected form');
const COL = { COL_ORDER_GRB: 0, COL_ORDER_RGB: 1, COL_ORDER_HUB75_GRB: maxOrder };
const [normLo, normHi, normDefault] = normText.slice(1, 4).map(s => (s in COL) ? COL[s] : +s);
const norm = co => { co &= 0x0F; return (co >= normLo && co <= normHi) ? co : normDefault; };
// mirrors hub75RemapColorPins()
function remap(g, co) {
  const in1 = [g.r1, g.g1, g.b1], in2 = [g.r2, g.g2, g.b2], k1 = ['r1', 'g1', 'b1'], k2 = ['r2', 'g2', 'b2'];
  const out = { ...g }, s = lineSrc[norm(co)];
  for (let line = 0; line < 3; line++) { out[k1[s[line]]] = in1[line]; out[k2[s[line]]] = in2[line]; }
  return out;
}
// data that reaches the panel's physical R, G, B lines (upper half) for logical colour r,g,b
function lines(co, r, g, b) {
  const q = remap(M1, co), L = {};
  L[lineOfPin[q.r1]] = r; L[lineOfPin[q.g1]] = g; L[lineOfPin[q.b1]] = b;
  return [L.R, L.G, L.B];
}
// same for the lower half (r2,g2,b2)
function lines2(co, r, g, b) {
  const q = remap(M1, co), L = {};
  L[lineOfPin[q.r2]] = r; L[lineOfPin[q.g2]] = g; L[lineOfPin[q.b2]] = b;
  return [L.R, L.G, L.B];
}
// WLED-MM PR #349 per-pixel switch (data on R,G,B lines)
const mm = (o, r, g, b) => ({ 0: [g, r, b], 1: [r, g, b], 2: [b, r, g], 3: [r, b, g], 4: [b, g, r], 5: [g, b, r] })[o];
// WLED PolyBus wire order: first byte -> panel R line, second -> G, third -> B
const poly = (o, r, g, b) => ({ 1: [r, g, b], 2: [b, r, g], 3: [r, b, g], 4: [b, g, r], 5: [g, b, r] })[o];
const sorted = g => Object.values(g).sort((a, b) => a - b).join();

test('table shape', () => {
  assert.strictEqual(maxOrder, 6);
  assert.strictEqual(lineSrc.length, maxOrder + 1);
  for (const row of lineSrc) assert.deepStrictEqual([...row].sort(), [0, 1, 2]);
});

test('stored 0 (factory and default value) can never select a swap', () => {
  assert.deepStrictEqual([normLo, normHi, normDefault], [1, maxOrder, 1]); // 0 falls back to RGB
  assert.deepStrictEqual(lineSrc[0], [0, 1, 2]);                           // and its row is the identity anyway
});

test('every stored value permutes the same six GPIOs', () => {
  for (let co = 0; co <= 0xFF; co++) assert.strictEqual(sorted(remap(M1, co)), sorted(M1), `order ${co}`);
});

test('values shipped units hold keep the original pins (no swap)', () => {
  for (const co of [0, 1, 7, 8, 15, 0x10, 0x11, 0xF0]) assert.deepStrictEqual(remap(M1, co), M1, `stored ${co}`);
});

test('BGR (4) matches the former r<->b pin swap', () => {
  const bgr = { ...M1 };
  [bgr.r1, bgr.b1] = [bgr.b1, bgr.r1];
  [bgr.r2, bgr.b2] = [bgr.b2, bgr.r2];
  assert.deepStrictEqual(remap(M1, 4), bgr);
});

test('orders 1..5 match PolyBus and WLED-MM #349, both panel halves', () => {
  for (const o of [1, 2, 3, 4, 5]) for (const [r, g, b] of [[255, 0, 0], [0, 255, 0], [0, 0, 255], [10, 20, 30]]) {
    assert.deepStrictEqual(lines(o, r, g, b), poly(o, r, g, b), `order ${o} vs PolyBus`);
    assert.deepStrictEqual(lines(o, r, g, b), mm(o, r, g, b), `order ${o} vs WLED-MM`);
    assert.deepStrictEqual(lines2(o, r, g, b), lines(o, r, g, b), `order ${o} lower half`);
  }
});

test('RBG (3) swaps green and blue: the customer panel', () => {
  assert.deepStrictEqual(lines(3, 0, 255, 0), [0, 0, 255]); // green data leaves on the panel's B input
  assert.deepStrictEqual(lines(3, 0, 0, 255), [0, 255, 0]); // blue data leaves on the panel's G input
  assert.deepStrictEqual(lines(3, 255, 0, 0), [255, 0, 0]);
});

test('HUB75-only GRB (6) is a real red/green swap', () => {
  assert.deepStrictEqual(lines(6, 10, 20, 30), mm(0, 10, 20, 30));
});
// AI: end
